                                f'<div style="font-size:22px;font-weight:900;color:{_vc}">{_val}</div>'
                                f'<div style="font-size:10px;color:rgba(0,0,0,0.45);font-weight:600">{_lbl}</div>'
                                f'</div>',
                                unsafe_allow_html=True,
