                                f'</div>'
                                f'<div style="font-size:11px;color:rgba(0,0,0,0.45);margin-top:4px;font-style:italic">{_ats.get("one_line_verdict","")}</div>'
                                f'</div>'
                                f'</div>'
                                f'</div>',
